fn error_unsupported_lang(val: &str) -> ! {
    eprintln!("error: \"{}\" isn't a valid value for '--supported-language <SUPPORTED_LANGUAGE>'", val);
    eprintln!("        [possible values: english, english1k, english10k]");
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    executable --supported-language <SUPPORTED_LANGUAGE>");
    eprintln!();
    eprintln!("For more information try --help");
    std::process::exit(2);
}

fn error_invalid_value(flag: &str, placeholder: &str, val: &str) -> ! {
    eprintln!("error: Invalid value \"{}\" for '{} <{}>': invalid digit found in string", val, flag, placeholder);
    eprintln!();
    eprintln!("For more information try --help");
    std::process::exit(2);
}

fn error_unknown_arg(arg: &str) -> ! {
    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", arg);
    eprintln!();
    eprintln!("        If you tried to supply `{}` as a value rather than a flag, use `-- {}`", arg, arg);
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    executable [OPTIONS]");
    eprintln!();
    eprintln!("For more information try --help");
    std::process::exit(2);
}

fn error_stdin_tty() -> ! {
    eprintln!("error: stdin must be a tty");
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    thokr [OPTIONS]");
    eprintln!();
    eprintln!("For more information try --help");
    std::process::exit(2);
}

fn parse_args() -> Config {
    let args: Vec<String> = std::env::args().collect();
    let mut num_words: usize = 15;
    let mut num_secs: Option<u64> = None;
    let mut num_sentences: Option<usize> = None;
    let mut language = Language::English;
    let mut prompt_custom: Option<String> = None;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-h" | "--help" => {
                print_help();
                std::process::exit(0);
            }
            "-V" | "--version" => {
                print_version();
                std::process::exit(0);
            }
            "-l" | "--supported-language" => {
                if i+1 >= args.len() {
                    error_unsupported_lang("");
                }
                let val = args[i+1].clone();
                i+=1;
                match Language::from_str(&val) {
                    Some(l) => language = l,
                    None => error_unsupported_lang(&val),
                }
            }
            "-w" | "--number-of-words" => {
                if i+1 >= args.len() {
                    error_invalid_value("--number-of-words", "NUMBER_OF_WORDS", "");
                }
                let val = args[i+1].clone();
                i+=1;
                match val.parse::<usize>() {
                    Ok(v) => num_words = v,
                    Err(_) => error_invalid_value("--number-of-words", "NUMBER_OF_WORDS", &val),
                }
            }
            "-s" | "--number-of-secs" => {
                if i+1 >= args.len() {
                    error_invalid_value("--number-of-secs", "NUMBER_OF_SECS", "");
                }
                let val = args[i+1].clone();
                i+=1;
                match val.parse::<u64>() {
                    Ok(v) => num_secs = Some(v),
                    Err(_) => error_invalid_value("--number-of-secs", "NUMBER_OF_SECS", &val),
                }
            }
            "-f" | "--full-sentences" => {
                if i+1 >= args.len() {
                    error_invalid_value("--full-sentences", "NUMBER_OF_SENTENCES", "");
                }
                let val = args[i+1].clone();
                i+=1;
                match val.parse::<usize>() {
                    Ok(v) => num_sentences = Some(v),
                    Err(_) => error_invalid_value("--full-sentences", "NUMBER_OF_SENTENCES", &val),
                }
            }
            "-p" | "--prompt" => {
                if i+1 >= args.len() {
                    prompt_custom = Some(String::new());
                } else {
                    let val = args[i+1].clone();
                    i+=1;
                    prompt_custom = Some(val);
                }
            }
            _ => {
                if arg.starts_with("-") {
                    error_unknown_arg(arg);
                } else {
                    error_unknown_arg(arg);
                }
            }
        }
        i+=1;
    }

    Config {
        num_words,
        num_secs,
        num_sentences,
        language,
        prompt_custom,
    }
}

fn generate_prompt(config: &Config) -> String {
    if let Some(custom) = &config.prompt_custom {
        return custom.clone();
    }
    if let Some(n) = config.num_sentences {
        return generate_sentences(n);
    }
    let word_list = config.language.words();
    let mut rng = rand::thread_rng();
    let mut words = Vec::new();
    for _ in 0..config.num_words {
        if let Some(w) = word_list.choose(&mut rng) {
            words.push(w.clone());
        }
    }
    words.join(" ")
}

fn generate_sentences(n: usize) -> String {
    let word_list = Language::English1k.words();
    let mut rng = rand::thread_rng();
    let mut sentences = Vec::new();
    for _ in 0..n {
        let len = rng.gen_range(5..12);
        let mut words = Vec::new();
        for _ in 0..len {
            if let Some(w) = word_list.choose(&mut rng) {
                words.push(w.clone());
            }
        }
        if words.is_empty() {
            continue;
        }
        let mut first = words[0].clone();
        if let Some(c) = first.get(0..1) {
            let cap = c.to_uppercase();
            first = cap + &first[1..];
            words[0] = first;
        }
        let mut sentence = words.join(" ");
        sentence.push('.');
        sentences.push(sentence);
    }
    sentences.join(" ")
}

fn get_log_path() -> PathBuf {
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        let mut p = PathBuf::from(xdg);
        p.push("thokr");
        p.push("log.csv");
        return p;
    }
    if let Some(mut cfg) = dirs::config_dir() {
        cfg.push("thokr");
        cfg.push("log.csv");
        return cfg;
    }
    let home = std::env::var("HOME").unwrap_or_else(|_| "/tmp".to_string());
    let mut p = PathBuf::from(home);
    p.push(".config");
    p.push("thokr");
    p.push("log.csv");
    p
}

fn log_result(config: &Config, elapsed: f64, wpm_str: &str, accuracy: u64, std_dev: f64) {
    let path = get_log_path();
    if let Some(parent) = path.parent() {
        let _ = create_dir_all(parent);
    }
    let exists = path.exists();
    let mut file = OpenOptions::new().create(true).append(true).open(&path).unwrap();
    if !exists {
        let _ = writeln!(file, "date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev");
    }
    let date = Local::now().format("%a %b %e %H:%M:%S %Y").to_string();
    let num_words = config.num_words;
    let num_secs_str = match config.num_secs {
        Some(s) => format!("{:.2}", s as f64),
        None => String::new(),
    };
    let elapsed_str = format!("{:.2}", elapsed);
    let std_dev_str = format!("{:.2}", std_dev);
    let line = format!("{},{},{},{},{},{},{}", date, num_words, num_secs_str, elapsed_str, wpm_str, accuracy, std_dev_str);
    let _ = writeln!(file, "{}", line);
}

fn main() -> io::Result<()> {
    if !io::stdin().is_terminal() {
        error_stdin_tty();
    }

    let config = parse_args();
    let mut current_prompt = generate_prompt(&config);

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    stdout.execute(EnterAlternateScreen)?;
    stdout.execute(Hide)?;

    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut typed = String::new();
    let mut start_time: Option<Instant> = None;
    let mut wpm_history: Vec<(f64, f64)> = Vec::new();
    let mut last_sample = Instant::now();

    let mut final_elapsed = 0.0f64;
    let mut final_correct = 0usize;
    let mut final_accuracy = 0u64;
    let mut final_wpm_str = String::from("0");
    let mut final_std_dev = 0.0f64;

    let mut screen = 0;

    loop {
        if screen == 0 {
            if current_prompt.is_empty() {
                final_elapsed = 0.0;
                final_correct = 0;
                final_accuracy = 0;
                final_wpm_str = "0".to_string();
                final_std_dev = 0.0;
                screen = 1;
                log_result(&config, final_elapsed, &final_wpm_str, final_accuracy, final_std_dev);
                continue;
            }

            let elapsed = if let Some(st) = start_time {
                st.elapsed().as_secs_f64()
            } else {
                0.0
            };
            if let Some(num_secs) = config.num_secs {
                if let Some(_) = start_time {
                    if elapsed >= num_secs as f64 {
                        final_elapsed = num_secs as f64;
                        let correct = typed.chars().zip(current_prompt.chars()).filter(|(a,b)| a==b).count();
                        final_correct = correct;
                        let acc = if typed.is_empty() { 0 } else { ((correct as f64 * 100.0 / typed.len() as f64).round()) as u64 };
                        final_accuracy = acc.min(100);
                        let wpm_val = if final_correct == 0 {
                            0.0
                        } else {
                            let ceil_el = final_elapsed.ceil();
                            if ceil_el == 0.0 { 0.0 } else { (final_correct as f64 * 12.0 / ceil_el).ceil() }
                        };
                        final_wpm_str = format!("{}", wpm_val as u64);
                        let sd = if wpm_history.is_empty() { 0.0 } else {
                            let mean: f64 = wpm_history.iter().map(|(_, v)| v).sum::<f64>() / wpm_history.len() as f64;
                            let var: f64 = wpm_history.iter().map(|(_, v)| (v - mean).powi(2)).sum::<f64>() / wpm_history.len() as f64;
                            var.sqrt()
                        };
                        final_std_dev = sd;
                        screen = 1;
                        log_result(&config, final_elapsed, &final_wpm_str, final_accuracy, final_std_dev);
                        continue;
                    }
                }
            }

            if typed.len() >= current_prompt.len() {
                let elapsed_final = if let Some(st) = start_time { st.elapsed().as_secs_f64() } else { 0.0 };
                final_elapsed = elapsed_final;
                let correct = typed.chars().zip(current_prompt.chars()).filter(|(a,b)| a==b).count();
                final_correct = correct;
                let acc = if current_prompt.is_empty() { 0 } else { ((correct as f64 * 100.0 / current_prompt.len() as f64).round()) as u64 };
                final_accuracy = acc.min(100);
                let wpm_str = if final_elapsed < 0.001 {
                    "inf".to_string()
                } else {
                    let ceil_el = final_elapsed.ceil();
                    if ceil_el == 0.0 {
                        "inf".to_string()
                    } else {
                        let val = (final_correct as f64 * 12.0 / ceil_el).ceil();
                        if val.is_infinite() || val.is_nan() { "inf".to_string() } else { format!("{}", val as u64) }
                    }
                };
                final_wpm_str = wpm_str.clone();
                let sd = if wpm_history.is_empty() { 0.0 } else {
                    let mean: f64 = wpm_history.iter().map(|(_, v)| v).sum::<f64>() / wpm_history.len() as f64;
                    if wpm_history.len() == 1 { 0.0 } else {
                        let var: f64 = wpm_history.iter().map(|(_, v)| (v - mean).powi(2)).sum::<f64>() / wpm_history.len() as f64;
                        var.sqrt()
                    }
                };
                final_std_dev = sd;
                screen = 1;
                log_result(&config, final_elapsed, &final_wpm_str, final_accuracy, final_std_dev);
                continue;
            }

            terminal.draw(|f| {
                let size = f.area();
                let chunks = if config.num_secs.is_some() {
                    Layout::default()
                        .direction(Direction::Vertical)
                        .constraints([Constraint::Length(3), Constraint::Min(0)].as_ref())
                        .split(size)
                } else {
                    Layout::default()
                        .direction(Direction::Vertical)
                        .constraints([Constraint::Min(0)].as_ref())
                        .split(size)
                };

                let prompt_area = if config.num_secs.is_some() { chunks[1] } else { chunks[0] };

                if config.num_secs.is_some() {
                    let timer_chunk = chunks[0];
                    let remaining = if let Some(st) = start_time {
                        let elapsed = st.elapsed().as_secs_f64();
                        let rem = config.num_secs.unwrap() as f64 - elapsed;
                        if rem < 0.0 { 0.0 } else { rem }
                    } else {
                        config.num_secs.unwrap() as f64
                    };
                    let timer_text = format!("{:.1}", remaining);
                    let timer_paragraph = Paragraph::new(timer_text)
                        .style(Style::default().add_modifier(Modifier::BOLD).add_modifier(Modifier::DIM))
                        .alignment(Alignment::Center);
                    f.render_widget(timer_paragraph, timer_chunk);
                }

                let mut spans = Vec::new();
                for (i, c) in current_prompt.chars().enumerate() {
                    let style = if i < typed.len() {
                        let typed_char = typed.chars().nth(i).unwrap();
                        if typed_char == c {
                            Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)
                        } else {
                            Style::default().fg(Color::Red)
                        }
                    } else if i == typed.len() {
                        Style::default().add_modifier(Modifier::BOLD | Modifier::DIM | Modifier::UNDERLINED)
                    } else {
                        Style::default().add_modifier(Modifier::BOLD | Modifier::DIM)
                    };
                    spans.push(Span::styled(c.to_string(), style));
                }
                let line = Line::from(spans);
                let paragraph = Paragraph::new(line)
                    .alignment(Alignment::Center)
                    .wrap(ratatui::widgets::Wrap { trim: false });
                f.render_widget(paragraph, prompt_area);
            })?;

            if event::poll(Duration::from_millis(50))? {
                if let Event::Key(key) = event::read()? {
                    match key.code {
                        KeyCode::Esc => break,
                        KeyCode::Char(c) => {
                            if key.modifiers.contains(KeyModifiers::CONTROL) && (c == 'c' || c == 'C') {
                                break;
                            }
                            if start_time.is_none() {
                                start_time = Some(Instant::now());
                                last_sample = Instant::now();
                                wpm_history.clear();
                            }
                            if typed.len() < current_prompt.len() {
                                typed.push(c);
                            }
                            if let Some(st) = start_time {
                                let elapsed = st.elapsed().as_secs_f64();
                                if elapsed > 0.0 && last_sample.elapsed() > Duration::from_millis(100) {
                                    let correct = typed.chars().zip(current_prompt.chars()).filter(|(a,b)| a==b).count();
                                    let wpm = correct as f64 * 12.0 / elapsed;
                                    wpm_history.push((elapsed, wpm));
                                    last_sample = Instant::now();
                                }
                            }
                        }
                        KeyCode::Backspace => {
                            typed.pop();
                        }
                        KeyCode::Left => {
                            typed.clear();
                            start_time = None;
                            wpm_history.clear();
                        }
                        KeyCode::Right => {
                            current_prompt = generate_prompt(&config);
                            typed.clear();
                            start_time = None;
                            wpm_history.clear();
                        }
                        _ => {}
                    }
                }
            } else {
                if let Some(st) = start_time {
                    let elapsed = st.elapsed().as_secs_f64();
                    if elapsed > 0.0 && last_sample.elapsed() > Duration::from_millis(100) {
                        let correct = typed.chars().zip(current_prompt.chars()).filter(|(a,b)| a==b).count();
                        let wpm = correct as f64 * 12.0 / elapsed;
                        wpm_history.push((elapsed, wpm));
                        last_sample = Instant::now();
                    }
                }
            }
        } else {
            terminal.draw(|f| {
                let size = f.area();
                let chunks = Layout::default()
                    .direction(Direction::Vertical)
                    .constraints([
                        Constraint::Min(10),
                        Constraint::Length(3),
                        Constraint::Length(1),
                    ].as_ref())
                    .split(size);

                let max_elapsed = if final_elapsed.ceil() < 1.0 { 1.0 } else { final_elapsed.ceil() };
                let max_wpm = if wpm_history.is_empty() {
                    if final_wpm_str == "inf" {
                        10.0
                    } else {
                        final_wpm_str.parse::<f64>().unwrap_or(10.0).max(1.0)
                    }
                } else {
                    wpm_history.iter().map(|(_, v)| *v).fold(0.0f64, |a,b| a.max(b)).max(1.0)
                };

                let data: Vec<(f64,f64)> = wpm_history.clone();

                let datasets = vec![
                    Dataset::default()
                        .name("wpm")
                        .marker(symbols::Marker::Braille)
                        .style(Style::default().fg(Color::Magenta))
                        .data(&data),
                ];

                let x_axis = Axis::default()
                    .title("seconds")
                    .style(Style::default().fg(Color::White))
                    .bounds([0.0, max_elapsed])
                    .labels(vec![
                        Span::styled("0", Style::default().add_modifier(Modifier::BOLD)),
                        Span::styled(format!("{:.2}", max_elapsed), Style::default().add_modifier(Modifier::BOLD)),
                    ]);

                let y_max_label = if final_wpm_str == "inf" {
                    "inf".to_string()
                } else {
                    format!("{}", max_wpm.ceil() as u64)
                };

                let y_axis = Axis::default()
                    .title("wpm")
                    .style(Style::default().fg(Color::White))
                    .bounds([0.0, max_wpm])
                    .labels(vec![
                        Span::styled("0", Style::default().add_modifier(Modifier::BOLD)),
                        Span::styled(y_max_label, Style::default().add_modifier(Modifier::BOLD)),
                    ]);

                let chart = Chart::new(datasets)
                    .block(Block::default())
                    .x_axis(x_axis)
                    .y_axis(y_axis);

                f.render_widget(chart, chunks[0]);

                let stats_text = format!("{} wpm   {}% acc   {:.2} sd", final_wpm_str, final_accuracy, final_std_dev);
                let stats_paragraph = Paragraph::new(stats_text)
                    .style(Style::default().add_modifier(Modifier::BOLD))
                    .alignment(Alignment::Center);
                f.render_widget(stats_paragraph, chunks[1]);

                let help_text = "(r)etry / (n)ew / (esc)ape";
                let help_par = Paragraph::new(help_text)
                    .style(Style::default().add_modifier(Modifier::ITALIC))
                    .alignment(Alignment::Center);
                f.render_widget(help_par, chunks[2]);
            })?;

            if event::poll(Duration::from_millis(100))? {
                if let Event::Key(key) = event::read()? {
                    match key.code {
                        KeyCode::Esc => break,
                        KeyCode::Char('r') | KeyCode::Char('R') => {
                            typed.clear();
                            start_time = None;
                            wpm_history.clear();
                            screen = 0;
                        }
                        KeyCode::Char('n') | KeyCode::Char('N') => {
                            current_prompt = generate_prompt(&config);
                            typed.clear();
                            start_time = None;
                            wpm_history.clear();
                            screen = 0;
                        }
                        KeyCode::Left => {
                            typed.clear();
                            start_time = None;
                            wpm_history.clear();
                            screen = 0;
                        }
                        KeyCode::Right => {
                            current_prompt = generate_prompt(&config);
                            typed.clear();
                            start_time = None;
                            wpm_history.clear();
                            screen = 0;
                        }
                        KeyCode::Char(c) => {
                            if key.modifiers.contains(KeyModifiers::CONTROL) && (c=='c' || c=='C') {
                                break;
                            }
                        }
                        _ => {}
                    }
                }
            }
        }
    }

    disable_raw_mode()?;
    terminal.backend_mut().execute(LeaveAlternateScreen)?;
    terminal.backend_mut().execute(Show)?;

    Ok(())
}
