#[derive(Debug, Clone, PartialEq)]
enum Language {
    English,
    English1k,
    English10k,
}

impl Language {
    fn from_str(s: &str) -> Option<Self> {
        match s {
            "english" => Some(Language::English),
            "english1k" => Some(Language::English1k),
            "english10k" => Some(Language::English10k),
            _ => None,
        }
    }
    fn words(&self) -> Vec<String> {
        match self {
            Language::English => ENGLISH_200.iter().map(|s| s.to_string()).collect(),
            Language::English1k => ENGLISH_1K.iter().map(|s| s.to_string()).collect(),
            Language::English10k => {
                let v = en10k_embed::ENGLISH_10K_EMBED;
                if v.len() >= 1000 {
                    v.iter().map(|s| s.to_string()).collect()
                } else {
                    ENGLISH_1K.iter().map(|s| s.to_string()).collect()
                }
            }
        }
    }
}

